/** Replies generated by the terminal parser, never keyboard, paste or mouse input. */
export function isTerminalResponse(data: string): boolean {
  return /^(?:\x1b\[[?>]?[\d;]*(?:[Rcntu]|\$y)|\x1bP(?:[01]\$r|>\|)[^\x1b]*\x1b\\|\x1b\](?:4;\d+|10|11|12);[^\x07\x1b]*(?:\x07|\x1b\\))+$/.test(data);
}
